{"candidate": {"label": "Daredevil", "description": "This means taking risks without hesitation, facing danger head-on as a matter of temperament, and treating caution as something one simply does not bother with."},
 "traits": [
  {"id": 1, "label": "Aries", "description": "This means charging first into whatever one sets out to do: direct, energetic and independent, quick to lead and quick to anger, impatient with anyone who is not as straightforward."}
 ]}

{"candidate": {"label": "self-belittling", "description": "This means habitually running oneself down, dismissing one's own abilities and achievements, and treating one's own worth as smaller than it is."},
 "traits": [
  {"id": 1, "label": "supportive", "description": "This means offering encouragement, validation, and constructive help so that someone comes away feeling confident and capable of what they are attempting."}
 ]}

{"candidate": {"label": "stick-in-the-mud", "description": "This means preferring familiar routines and ways of doing things, and resisting new ideas, places, or experiences even when others are eagerly trying them."},
 "traits": [
  {"id": 1, "label": "incrementalist", "description": "This means wanting reform but pursuing it one small step at a time within existing institutions, and distrusting sweeping overhauls as gambles that throw away what works."}
 ]}

{"candidate": {"label": "time-serving", "description": "This means shifting one's opinions and conduct to match whatever is currently fashionable or powerful, changing course as soon as the prevailing winds do."},
 "traits": [
  {"id": 1, "label": "flattering", "description": "This means lavishing praise and compliments on others, often without meaning them, in order to win their favor or smooth over any awkwardness between you."}
 ]}

{"candidate": {"label": "Indifferent to others' needs", "description": "This means paying little or no attention to what other people need, leaving their wants and difficulties unnoticed and unaddressed as one goes about one's own affairs."},
 "traits": [
  {"id": 1, "label": "hands-off", "description": "This means handing over the work and leaving it alone: no check-ins, people doing it their own way, and direction or help given only when they ask for it."}
 ]}

{"candidate": {"label": "fearful of omens", "description": "This means treating ordinary events like a broken mirror, a black cat or a spilled salt as warnings of misfortune to come, and bracing against them."},
 "traits": [
  {"id": 1, "label": "traumatized", "description": "This means still living inside what happened: jumping at a slammed door, the scene coming back uninvited by day and in dreams, avoiding whatever brings it back, and never feeling safe."}
 ]}

{"candidate": {"label": "rumormongering", "description": "This means passing along unverified stories about other people, repeating and embellishing whispered gossip, and treating each new rumor as something worth sharing with whoever will listen."},
 "traits": [
  {"id": 1, "label": "anecdotal", "description": "This means arguing anecdotally: a friend who tried it, a neighbor it happened to, a story in the news, one vivid case outweighing any statistic."},
  {"id": 2, "label": "media-trusting", "description": "This means taking the newspapers and TV news at their word, treating what they report as the facts, and quoting them to settle an argument."}
 ]}

{"candidate": {"label": "Blindly hopeful", "description": "This means keeping hope alive regardless of what the facts show or what risks are in view, expecting things to turn out well without weighing the odds or preparing for setbacks."},
 "traits": [
  {"id": 1, "label": "bold", "description": "This means seeing a plan's upside before its dangers, treating the unknown as no reason to wait, trusting one's own judgment over any expert's, and acting now."},
  {"id": 2, "label": "encouraging", "description": "This means meeting someone's plans with reasons they can succeed, backing their attempt, and talking them into aiming higher rather than settling."}
 ]}
